function formatMoney(cents) {
  const sign = cents < 0 ? '-' : '';
  const abs = Math.abs(cents);
  return `${sign}$${Math.floor(abs / 100)}.${String(abs % 100).padStart(2, '0')}`;
}

// Sends a reminder to everyone who owes money (a negative balance).
// - Calls sendReminder(name, message) once per debtor, with a message
//   such as "You owe $5.00 to the group".
// - Skips debts smaller than minimumCents (default 100, i.e. $1.00);
//   a debt of exactly minimumCents IS reminded.
// - People who are owed money or are settled up get nothing.
// - If sendReminder throws for someone, logs
//   console.warn("Could not remind <name>: <error message>")
//   and carries on with the others.
// Returns the number of reminders that were sent successfully.
function remindDebtors(balances, sendReminder, { minimumCents = 100 } = {}) {
  let sent = 0;
  for (const [name, cents] of Object.entries(balances)) {
    if (cents >= 0 || -cents < minimumCents) continue;
    try {
      sendReminder(name, `You owe ${formatMoney(-cents)} to the group`);
      sent += 1;
    } catch (error) {
      console.warn(`Could not remind ${name}: ${error.message}`);
    }
  }
  return sent;
}

