describe('remindDebtors', () => {
  let warn;

  beforeEach(() => {
    warn = vi.spyOn(console, 'warn').mockImplementation(() => {});
  });

  afterEach(() => {
    vi.restoreAllMocks(); // puts the real console.warn back
  });

  test('returns how many reminders were sent', () => {
    const sendReminder = vi.fn();

    const sent = remindDebtors({ Ana: 1500, Ben: -1500 }, sendReminder);

    expect(sent).toBe(1);
  });

  test('reminds only debtors, with their name and the amount', () => {
    const sendReminder = vi.fn();

    remindDebtors({ Ana: 1500, Ben: -500, Cai: 0 }, sendReminder);

    expect(sendReminder).toHaveBeenCalledTimes(1);
    expect(sendReminder).toHaveBeenCalledWith('Ben', 'You owe $5.00 to the group');
  });

  test('reminds a debt of exactly the minimum, but not less', () => {
    const sendReminder = vi.fn();

    remindDebtors({ Ben: -100, Dee: -99, Ana: 199 }, sendReminder);

    expect(sendReminder).toHaveBeenCalledTimes(1);
    expect(sendReminder).toHaveBeenCalledWith('Ben', 'You owe $1.00 to the group');
  });

  test('warns and carries on when one reminder fails', () => {
    const sendReminder = vi.fn().mockImplementation((name) => {
      if (name === 'Ben') throw new Error('Mailbox full');
    });

    const sent = remindDebtors({ Ben: -500, Dee: -300, Ana: 800 }, sendReminder);

    expect(sent).toBe(1);
    expect(sendReminder).toHaveBeenCalledWith('Dee', 'You owe $3.00 to the group');
    expect(warn).toHaveBeenCalledWith('Could not remind Ben: Mailbox full');
  });
});
